#include <stdio.h>

int main(void) {
    constexpr int LIBRI_TOTALI = 535;
    constexpr int LIBRI_PER_SCATOLA = 12;
    constexpr int SCATOLE_PER_BANCALE = 8;
    constexpr double PESO_CAMPIONE_KG = 3.0;
    constexpr double LIBRI_CAMPIONE = 8.0;

    int scatole_complete = LIBRI_TOTALI / LIBRI_PER_SCATOLA;
    int libri_sfusi = LIBRI_TOTALI % LIBRI_PER_SCATOLA;
    int bancali_completi = scatole_complete / SCATOLE_PER_BANCALE;
    int scatole_avanzate = scatole_complete % SCATOLE_PER_BANCALE;
    int libri_su_bancali = bancali_completi * SCATOLE_PER_BANCALE * LIBRI_PER_SCATOLA;
    double peso_medio_kg = PESO_CAMPIONE_KG / LIBRI_CAMPIONE;

    printf("Libri totali: %d\n", LIBRI_TOTALI);
    printf("Scatole complete: %d (libri sfusi: %d)\n", scatole_complete, libri_sfusi);
    printf("Bancali completi: %d (scatole avanzate: %d)\n", bancali_completi, scatole_avanzate);
    printf("Libri su bancali completi: %d\n", libri_su_bancali);
    printf("Peso medio di un libro: %.3f kg\n", peso_medio_kg);
    return 0;
}

#include <stdio.h>

int main(void) {
    int punti = 50;
    int tappe = 0;

    // Prima tappa
    ++tappe;
    punti += 30;

    // Seconda tappa
    punti *= 2;
    ++tappe;

    // Terza tappa
    punti -= 15;
    punti /= 3;
    ++tappe;

    int bonus_pre = 10;
    int bonus_post = 10;
    int val_pre = ++bonus_pre;
    int val_post = bonus_post++;

    int senza_parentesi = 10 + 4 * 3 - 6 / 2;
    int con_parentesi = (10 + 4) * 3 - 6 / 2;

    printf("Tappe completate: %d\n", tappe);
    printf("Punteggio finale: %d\n", punti);
    printf("Pre-incremento: valore=%d, variabile=%d\n", val_pre, bonus_pre);
    printf("Post-incremento: valore=%d, variabile=%d\n", val_post, bonus_post);
    printf("Senza parentesi: %d\n", senza_parentesi);
    printf("Con parentesi: %d\n", con_parentesi);
    return 0;
}

#include <stdio.h>

int main(void) {
    int batteria = 68;
    int vento_kmh = 22;
    int temperatura_c = 14;
    int modalita_volo = 2;
    bool gps_attivo = true;
    bool pioggia = false;

    bool batteria_ok = (batteria >= 30);
    bool vento_ok = (vento_kmh < 35);
    bool temperatura_ok = (temperatura_c >= 0 && temperatura_c <= 40);
    bool modalita_ok = (modalita_volo != 0);
    bool meteo_ok = (vento_ok && temperatura_ok && !pioggia);
    bool pronto_al_volo = (batteria_ok && meteo_ok && modalita_ok && gps_attivo);
    bool allerta = (batteria < 20 || !gps_attivo);

    printf("=== CONTROLLO PRE-VOLO DRONE ===\n");
    printf("Batteria sufficiente : %d\n", batteria_ok);
    printf("Vento sicuro         : %d\n", vento_ok);
    printf("Temperatura valida   : %d\n", temperatura_ok);
    printf("Modalita attiva      : %d\n", modalita_ok);
    printf("Meteo favorevole     : %d\n", meteo_ok);
    printf("Pronto al volo       : %d\n", pronto_al_volo);
    printf("Allerta attiva       : %d\n", allerta);
    return 0;
}

#include <stddef.h>
#include <stdio.h>

int main(void) {
    int favorevoli = 118;
    int contrari = 39;
    int astenuti = 18;
    int totale = favorevoli + contrari + astenuti;
    constexpr int SEGGI_TOTALI = 15;

    int perc_intera = favorevoli * 100 / totale;
    double perc_tardiva = (double)(favorevoli / totale) * 100.0;
    double perc_favorevoli = (double)favorevoli * 100.0 / totale;
    double perc_contrari = (double)contrari * 100.0 / totale;
    double perc_astenuti = (double)astenuti * 100.0 / totale;

    double quota_comitato = (double)favorevoli / totale * SEGGI_TOTALI;
    int seggi_assegnati = (int)quota_comitato;

    short quota_a = 1200;
    short quota_b = 350;
    int somma_quote = quota_a + quota_b;
    size_t dim_espressione = sizeof(quota_a + quota_b);

    printf("Totale risposte: %d\n", totale);
    printf("Percentuale intera favorevoli: %d%%\n", perc_intera);
    printf("Cast tardivo (errato): %.2f%%\n", perc_tardiva);
    printf("Favorevoli: %.2f%%\n", perc_favorevoli);
    printf("Contrari: %.2f%%\n", perc_contrari);
    printf("Astenuti: %.2f%%\n", perc_astenuti);
    printf("Quota comitato (15 seggi): %.2f -> seggi assegnati: %d\n",
           quota_comitato, seggi_assegnati);
    printf("Somma quote short: %d (dimensione espressione: %zu byte)\n",
           somma_quote, dim_espressione);
    return 0;
}

#include <math.h>
#include <stdio.h>

int main(void) {
    constexpr double LUNGHEZZA = 7.4;
    constexpr double LARGHEZZA = 4.8;
    constexpr double RESA_SCATOLA = 1.44;
    constexpr double PREZZO_SCATOLA = 48.75;
    constexpr double BUDGET = 1200.0;
    constexpr double LUNGHEZZA_ROTOLO = 3.5;
    constexpr double CAPITALE_INIZIALE = 1000.0;
    constexpr double FATTORE_ANNUO = 1.04;
    constexpr double ANNI = 3.0;

    double area = LUNGHEZZA * LARGHEZZA;
    double perimetro = 2.0 * (LUNGHEZZA + LARGHEZZA);
    double diagonale = sqrt(LUNGHEZZA * LUNGHEZZA + LARGHEZZA * LARGHEZZA);
    double scatole = ceil(area / RESA_SCATOLA);
    double rotoli_completi = floor(perimetro / LUNGHEZZA_ROTOLO);
    double resto_perimetro = fmod(perimetro, LUNGHEZZA_ROTOLO);
    double costo_piastrelle = scatole * PREZZO_SCATOLA;
    double costo_arrotondato = round(costo_piastrelle);
    double scostamento = fabs(costo_piastrelle - BUDGET);
    double fondo_finale = CAPITALE_INIZIALE * pow(FATTORE_ANNUO, ANNI);

    printf("Area terrazza: %.2f mq\n", area);
    printf("Diagonale: %.2f m\n", diagonale);
    printf("Scatole necessarie: %.0f\n", scatole);
    printf("Perimetro: %.2f m (rotoli completi: %.0f, resto: %.2f m)\n",
           perimetro, rotoli_completi, resto_perimetro);
    printf("Costo piastrelle: %.2f euro (arrotondato: %.0f euro)\n",
           costo_piastrelle, costo_arrotondato);
    printf("Scostamento dal budget: %.2f euro\n", scostamento);
    printf("Fondo dopo 3 anni: %.2f euro\n", fondo_finale);
    return 0;
}

#include <float.h>
#include <limits.h>
#include <math.h>
#include <stdio.h>

int main(void) {
    int a = 2'000'000'000;
    int b = 500'000'000;
    bool somma_sicura_int = (a <= INT_MAX - b);
    long long somma_esatta = (long long)a + b;

    unsigned int max_u = UINT_MAX;
    unsigned int dopo_wrap = max_u + 1U;
    unsigned int sotto_zero = 0U - 1U;

    double somma_dec = 0.1 + 0.1 + 0.1;
    double atteso = 0.3;
    bool uguali_esatti = (somma_dec == atteso);
    double errore = fabs(somma_dec - atteso);
    bool uguali_tolleranza = (errore <= 1e-12);

    printf("Somma sicura in int: %d\n", somma_sicura_int);
    printf("Somma esatta in long long: %lld\n", somma_esatta);
    printf("Unsigned UINT_MAX + 1U: %u\n", dopo_wrap);
    printf("Unsigned 0U - 1U: %u\n", sotto_zero);
    printf("0.1 + 0.1 + 0.1 = %.17f\n", somma_dec);
    printf("0.3             = %.17f\n", atteso);
    printf("Confronto con == : %d\n", uguali_esatti);
    printf("Errore assoluto  : %e\n", errore);
    printf("Confronto tolleranza (1e-12): %d\n", uguali_tolleranza);
    printf("Precisione cifre: float=%d, double=%d\n", FLT_DIG, DBL_DIG);
    printf("Epsilon: float=%e, double=%e\n", FLT_EPSILON, DBL_EPSILON);
    return 0;
}
